<script>
  /**
   * Renders ability description HTML that was generated by tools/lib/extract.js
   * from the wiki. That generator only ever emits a small allow-list of tags
   * (`b`, `i`, `em`, `strong`, `span`, `a`, `li`, `ul`, `dl`, `dt`, `dd`, `br`)
   * and strips every attribute except `class`, `href` and `title`; it never
   * emits `script`, event handlers or `javascript:` URLs.
   */
  import { markRankNumbers } from '../format.js'

  let { html } = $props()

  const marked = $derived(markRankNumbers(html ?? ''))
</script>

<div class="ability-desc">{@html marked}</div>
